#!/usr/bin/env node
// Tender till: every board composed from the saas-design kit (kit.css), the Tender tokens and till.css.
// Writes out/<Name>.html for review and ../till-canvas/project/<Name>.dc.html for the canvas.
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const here = path.dirname(fileURLToPath(import.meta.url));
const KIT = "/Users/user/Library/Application Support/Claude/local-agent-mode-sessions/b7d94d8a-a046-4159-ad33-19d70dd8e185/f83d1a09-511c-45a3-835c-21ea18df88cf/rpm/plugin_016y1JuvTBpaaQRF4NAUXyUn/skills/component-kit/assets/kit.css";
const OUT = path.join(here, "out");
const CANVAS = path.join(here, "..", "till-canvas", "project");
fs.mkdirSync(OUT, { recursive: true });

const PH = JSON.parse(fs.readFileSync(path.join(here, "node_modules/@iconify-json/ph/icons.json"), "utf8"));
const LG = JSON.parse(fs.readFileSync(path.join(here, "node_modules/@iconify-json/logos/icons.json"), "utf8"));

// ── Primitives ──────────────────────────────────────────────────────────────
const ic = (n, cls = "") => {
  const i = PH.icons[n + "-fill"] || PH.icons[n];
  if (!i) throw new Error("no icon " + n);
  return `<svg class="ic${cls ? " " + cls : ""}" viewBox="0 0 256 256" aria-hidden="true">${i.body}</svg>`;
};
let lid = 0;
const logo = (n, label) => {
  const i = LG.icons[n]; const w = i.width || LG.width || 256, h = i.height || LG.height || 256; const k = "l" + (++lid) + "-";
  const body = i.body.replace(/id="([^"]+)"/g, (m, x) => `id="${k}${x}"`).replace(/url\(#([^)]+)\)/g, (m, x) => `url(#${k}${x})`);
  return `<span class="mark" style="width:32px;height:20px;border-radius:4px"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}">${body}</svg></span>`;
};
const CARD = () => `<span class="mark-pair">${logo("visa", "Visa")}${logo("mastercard", "Mastercard")}</span>`;
const btn = (label, icon, cls = "", attrs = "") => `<button class="btn${cls ? " " + cls : ""}"${attrs}>${icon ? ic(icon) : ""}${label}</button>`;
const abtn = (label, icon, href, cls = "") => `<a class="btn${cls ? " " + cls : ""}" href="${href}.dc.html">${icon ? ic(icon) : ""}${label}</a>`;
const kbdIn = (k) => `<span class="kbd" style="margin-left:var(--space-4);background:transparent;color:inherit;box-shadow:inset 0 0 0 1px rgba(255,255,255,.32)">${k}</span>`;
const avatar = (size = 32) => `<span class="avatar avatar-${size} avatar-none">${ic("user")}</span>`;
const status = (word, kind = "") => `<span class="status${kind ? " status-" + kind : ""}">${word}</span>`;
const keypad = (opts = {}) => {
  const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9"].map((d) => `<button>${d}</button>`).join("");
  const left = opts.dot ? `<button>.</button>` : opts.left ? `<button class="quiet">${opts.left}</button>` : `<span></span>`;
  const zero = opts.zeroHref ? `<a href="${opts.zeroHref}.dc.html" style="display:contents"><button>0</button></a>` : `<button>0</button>`;
  return `<div class="keypad" role="group" aria-label="Number pad" data-lint-ignore="B1">${keys}${left}${zero}<button aria-label="Delete the last digit">${ic("backspace")}</button></div>`;
};
const pinDots = (n, wrong = false) => `<div class="pin${wrong ? " is-wrong" : ""}" role="img" aria-label="${n} of 4 digits typed">${[0, 1, 2, 3].map((i) => `<i class="${i < n ? "on" : ""}"></i>`).join("")}</div>`;

// ── The world ───────────────────────────────────────────────────────────────
const GEN_TILES = [
  ["US$1.20", "Tomatoes, loose, a kg", "17 kg left"], ["US$6.00", "Potatoes, pocket", "9 left"], ["US$0.20", "Eggs, each", "84 left"],
  ["US$1.00", "Bread, white loaf", "26 left"], ["US$8.50", "Roller meal, 10kg", "21 left"], ["US$4.20", "Cooking oil, 2L", "4 left", "low"],
  ["US$2.40", "Sugar, 2kg", "18 left"], ["US$2.80", "Rice, 2kg", "15 left"], ["US$3.10", "Washing powder, 1kg", "12 left"],
  ["US$2.00", "Coke, 2L", "30 left"], ["US$0.10", "Matches, box", "120 left"], ["Any", "Airtime", "Type the amount"],
];
const S5080 = [["Tomatoes, loose", "1.400", "US$1.68", "", { t: "kg at US$1.20 a kg" }], ["Eggs", "6", "US$1.20"], ["Bread, white loaf", "1", "US$1.00"], ["Roller meal, 10kg", "1", "US$8.50"],
  ["Cooking oil, 2L", "1", "US$4.20"], ["Washing powder, 1kg", "1", "US$3.10"], ["Coke, 2L", "1", "US$2.00"]];
const GEN = { shop: "Mbare Corner Groceries", till: "Till 1", who: "Rudo Moyo", clock: "08:14" };

// ── The till shell: a workbench with its navigation in the bar ──────────────
const bar = (o = {}) => {
  const sync = o.offline
    ? `<a class="btn btn-quiet" href="Waiting.dc.html">${ic("wifi-slash")}3 waiting to send</a>`
    : `<span class="status status-success" style="font-size:var(--text-13);color:var(--color-muted)">Up to date</span>`;
  const nav = `<div class="btn-group" role="group" aria-label="The till"><a class="btn" href="Held.dc.html">${ic("pause-circle")}Held <span class="muted num" style="text-align:left">2</span></a><a class="btn" href="History.dc.html">${ic("receipt")}History</a><a class="btn" href="Shift.dc.html">${ic("cash-register")}Shift</a></div>`;
  return `<div class="bar"><h1>${o.title || "Till 1"}</h1><span class="muted" style="font-size:var(--text-13)">${o.sub || GEN.shop}</span><div class="end">${sync}${o.shellA ? nav + `<a class="btn" href="Menu.dc.html">${avatar(24).replace("avatar-24 ", "")}${o.who || GEN.who}${ic("caret-up-down")}</a>` : ""}</div></div>`;
};
const search = (value = "", placeholder = "Scan a barcode or type a product") => `<div class="tools"><label class="input-wrap input-lg grow">${ic("barcode")}<input type="search" aria-label="Scan or search products" placeholder="${placeholder}"${value ? ` value="${value}"` : ""}><span class="kbd">/</span></label></div>`;
const groups = (names) => `<div class="tools" style="box-shadow:none;padding-bottom:0"><div class="seg" role="tablist" aria-label="Product groups">${names.map((g, i) => `<button role="tab" aria-selected="${i === 0}">${g}</button>`).join("")}</div></div>`;
const GLYPH = [[/tomato/i, "carrot"], [/potato/i, "carrot"], [/egg/i, "egg"], [/bread/i, "bread"], [/roller meal|rice|sugar/i, "grains"], [/oil/i, "drop"], [/washing|soap/i, "package"],
  [/coke|coca-cola/i, "pint-glass"], [/match/i, "flame"], [/airtime/i, "sim-card"], [/lager|beer/i, "beer-bottle"], [/walker|whisky/i, "martini"], [/savanna|cider/i, "beer-stein"], [/red|wine/i, "wine"], [/ice/i, "cube"], [/bottles back/i, "arrows-counter-clockwise"]];
const pic = (n) => { const g = (GLYPH.find(([r]) => r.test(n)) || [0, "package"])[1]; return `<span class="pic" aria-hidden="true">${ic(g)}</span>`; };
const tile = ([p, n, s, kind, href, extra]) => {
  const dis = kind === "off";
  const inner = `${pic(n)}<span class="p">${p}</span><span class="n">${n}</span>${extra || ""}<span class="s${kind === "low" ? " low" : ""}${kind === "age" ? " age" : ""}">${s}</span>`;
  if (href && !dis) return `<a class="tile" href="${href}.dc.html">${inner}</a>`;
  return `<button class="tile"${dis ? ' aria-disabled="true"' : ""}>${inner}</button>`;
};
const tiles = (list) => `<div class="tile-grid">${list.map(tile).join("")}</div>`;
const line = ([name, q, amt, unit, sub], o = {}) => {
  const qty = o.static ? `<span class="muted num" style="text-align:right">× ${q}</span>`
    : `<span class="qty" role="group" aria-label="Quantity of ${name}"><button aria-label="One fewer ${name}">${ic("minus")}</button><span>${q}</span><button aria-label="One more ${name}">${ic("plus")}</button></span>`;
  const label = `<span style="display:flex;flex-direction:column;min-width:0"><span class="truncate">${name}${unit ? ` <span class="muted">${unit}</span>` : ""}</span>${sub ? `<span class="meta truncate${sub.off ? " is-off" : ""}">${sub.t}</span>` : ""}</span>`;
  const inner = `${label}${qty}<span class="num">${amt}</span>`;
  return o.href ? `<a class="line" href="${o.href}.dc.html"${o.current ? ' aria-current="true"' : ""} style="color:inherit;text-decoration:none">${inner}</a>` : `<div class="line${o.cls ? " " + o.cls : ""}"${o.current ? ' aria-current="true"' : ""}>${inner}</div>`;
};
const payRows = (sel = "cash", o = {}) => {
  const rows = [
    ["cash", `${ic("money", "ic-20")}<span>Cash</span>`],
    ["card", `${CARD()}<span>Card <span class="meta">reference from the slip</span></span>`],
    ["mobile", `<span class="mark" style="width:24px;height:24px;border-radius:6px"><img src="__ECOCASH__" alt="EcoCash"></span><span>Mobile money <span class="meta">reference from their message</span></span>`],
    ["other", `${ic("ticket", "ic-20")}<span>Voucher or transfer</span>`],
  ];
  return `<div role="radiogroup" aria-label="How they are paying" style="display:flex;flex-direction:column;gap:var(--space-8);padding-top:var(--space-8)">${rows.map(([k, h]) => `<button class="pay" role="radio" aria-checked="${k === sel}"${o.disabled ? ' aria-disabled="true"' : ""}>${h}<span class="radio"></span></button>`).join("")}</div>`;
};
const sideHead = (o = {}) => {
  const cust = o.customer
    ? `<a class="btn btn-quiet" href="Customer.dc.html">${avatar(24).replace("avatar-24 ", "")}${o.customer}</a>`
    : `<a class="btn btn-quiet" href="Customer.dc.html">${ic("user-plus")}Add customer</a>`;
  return `<div class="bar"><h1>${o.title || "This sale"}</h1><span class="muted" style="font-size:var(--text-13)">${o.count || ""}</span><div class="end">${o.empty ? "" : `<a class="btn btn-quiet" href="Hold.dc.html">${ic("pause-circle")}Hold</a>`}${cust}</div></div>`;
};
const totalsBlock = (rows, total, o = {}) => {
  const r = rows.map(([a, b, off]) => `<div class="l"><span>${a}</span><span${off ? ' style="color:var(--color-success)"' : ""}>${b}</span></div>`).join("");
  const go = o.go || `<a class="btn btn-primary btn-touch btn-block" href="${o.goHref || "PayCash"}.dc.html">${ic("hand-coins")}Take ${total}${kbdIn("Enter")}</a>`;
  return `<div class="totals has-pin">${r}<div class="l total"><span>Total</span><span class="figure">${total}</span></div>${o.extra || ""}${o.pay === false ? "" : payRows(o.sel || "cash", { disabled: o.disabledPay })}<div class="pin-bottom">${go}</div>${o.why ? `<p class="help" style="text-align:center;font-size:var(--text-13);color:var(--color-ink-2)">${o.why}</p>` : ""}</div>`;
};
const R5080 = [["Before discounts", "US$21.68"], ["VAT where it applies, included", "US$0.68"]];
const sellScreen = (o = {}) => {
  const lines = o.lines === undefined ? S5080 : o.lines;
  const body = lines.length ? `<div class="list">${lines.map((l, i) => line(l, { href: o.lineHref === false ? null : (l[5] || "Line"), current: o.current === i, cls: l[6] })).join("")}${o.inBasket || ""}</div>`
    : `<div class="list" style="display:grid;place-items:center"><div class="empty" style="padding:var(--space-32) var(--space-24)">${ic("barcode", "glyph")}<h2>Scan the first product</h2><p>Or tap it below the search. The sale starts with it.</p></div></div>`;
  const tot = lines.length ? totalsBlock(o.rows || R5080, o.total || "US$21.68", o)
    : totalsBlock([], "US$0.00", { go: `<button class="btn btn-primary btn-touch btn-block" disabled>${ic("hand-coins")}Take US$0.00</button>`, pay: false });
  return `<div class="bench" style="grid-template-columns:minmax(0,1fr) 400px">
<main class="main">${o.bar || bar(o.barOpts)}${o.banner || ""}${search(o.query)}${o.groupsHtml || groups(o.groups || ["Most sold", "Groceries", "Fresh", "Drinks", "Household", "Airtime"])}${o.mainBody || tiles(o.tiles || GEN_TILES)}</main>
<aside class="bench-side" aria-label="This sale">${sideHead({ count: lines.length ? o.count || `${lines.length} items` : "", customer: o.customer, empty: !lines.length, title: o.saleTitle })}${body}${tot}${o.tray || ""}</aside></div>`;
};

// ── Boards ──────────────────────────────────────────────────────────────────
const BOARDS = [];
const board = (name, title, row, body, o = {}) => BOARDS.push({ name, title, row, body, w: o.w || 1280, h: o.h || 800, page: o.page || "general", phone: !!o.phone, css: o.css || "" });
const frame = (inner, extra = "") => `<div class="frame"${extra}>${inner}</div>`;
const over = (inner) => `<div class="over">${inner}</div>`;
const scrimDialog = (inner) => over(`<div class="scrim">${inner}</div>`);
const dialog = (h, p, foot, o = {}) => `<div class="dialog${o.lg ? " dialog-lg" : ""}" role="${o.alert ? "alertdialog" : "dialog"}" aria-labelledby="dlg-${o.id || "t"}">${o.head || ""}<div class="${o.lg ? "dialog-scroll" : "dialog-body"}">${o.lg ? "" : `<h2 id="dlg-${o.id || "t"}">${h}</h2>`}${p}</div><div class="dialog-foot">${foot}</div></div>`;

// Row 0: the shell, and the choice -------------------------------------------------
const R_SHELL = "The shell: a workbench, and the one other way it could go";
board("Sell", "Shell A, not chosen  The doors in the bar: Held, History, Shift, and a person menu", R_SHELL,
  frame(sellScreen({ customer: "Rufaro Chipunza", barOpts: { shellA: true } })));
const railItem = (i, l, on) => `<a class="nav" href="#"${on ? ' aria-current="page"' : ""} style="flex-direction:column;height:auto;padding:var(--space-8) 0;gap:var(--space-4);font-size:var(--text-12)">${ic(i, "ic-20")}<span>${l}</span></a>`;
board("ShellB", "Shell B, chosen 5 October  An icon rail: the person at the top, seven doors, Lock at the foot", R_SHELL,
  frame(sellScreen({ customer: "Rufaro Chipunza" })), { rail: "till" });

// Row 1: sell for cash ---------------------------------------------------------------
const R_CASH = "1  Rudo sells to Rufaro and takes cash";
board("SellEmpty", "Start: the scan field has focus, nothing to take yet", R_CASH, frame(sellScreen({ lines: [] })));
const custPop = `<div class="float" style="right:16px;top:56px"><div class="pop pop-arrow" role="dialog" aria-label="Add a customer" style="overflow:visible;width:360px"><div class="pop-body"><label class="input-wrap">${ic("magnifying-glass")}<input aria-label="Name, phone or email" value="0772 418"></label>
<div class="menu" style="box-shadow:none;padding:0;min-width:0"><a class="menu-item" href="Sell.dc.html" data-active="true" style="height:auto;padding:var(--space-8)">${avatar(32)}<span style="display:flex;flex-direction:column"><span style="color:var(--color-ink);font-weight:500">Rufaro Chipunza</span><span class="muted num" style="text-align:left;font-size:var(--text-12)">0772 418 902 · Silver · 1,240 points</span></span></a><a class="menu-item" href="Sell.dc.html" style="height:auto;padding:var(--space-8)">${avatar(32)}<span style="display:flex;flex-direction:column"><span style="color:var(--color-ink);font-weight:500">Tapiwa Mhlanga</span><span class="muted num" style="text-align:left;font-size:var(--text-12)">0772 418 330 · Bronze · 210 points</span></span></a><div class="menu-sep"></div><button class="menu-item">${ic("user-plus")}Add 0772 418 as a new customer</button></div></div>
<div class="pop-foot"><span class="kbd" style="margin-right:auto">Esc</span><a class="btn btn-ink" href="Sell.dc.html">${ic("user-check")}Put Rufaro on the sale</a></div></div></div>`;
board("Customer", "Add customer: a popover from the sale, search by phone or name", R_CASH, frame(sellScreen({}) .replace("</aside></div>", custPop + "</aside></div>")));
board("Sell1", "The sale: seven lines, Rufaro on it, cash already chosen", R_CASH, frame(sellScreen({ customer: "Rufaro Chipunza" })));
const trayCash = (o = {}) => over(`<div class="scrim" style="display:block;padding:0"></div><div class="tray" role="dialog" aria-label="Take cash"><div class="tray-top"><span class="text-heading" style="font-weight:600;color:var(--color-ink)">Total</span><span class="figure">${o.total || "US$21.68"}</span></div>${o.body}</div>`);
board("PayCash", "Take cash: what they handed over, the change, the same button", R_CASH, frame(sellScreen({ customer: "Rufaro Chipunza", tray: trayCash({ body:
  `<div class="tender"><span class="l">Cash handed over</span><span class="tender-figure">US$25.00</span></div><div class="quick" role="group" aria-label="Quick amounts" data-lint-ignore="B1">${btn("21.68", "", "btn-touch", ' aria-label="Exact, US$21.68"')}${btn("25.00", "", "btn-touch", ' aria-pressed="true" aria-label="US$25.00 handed over" style="box-shadow:0 0 0 1px var(--color-ink)"')}${btn("30.00", "", "btn-touch", ' aria-label="US$30.00 handed over"')}</div>${keypad({ dot: true })}<div class="wait" role="status" aria-live="polite"><span class="status status-success" style="color:var(--color-ink);font-weight:500">Change due</span><span class="num" style="font-size:var(--text-20);font-weight:600;color:var(--color-ink)">US$3.32</span></div><div class="grow"></div><a class="btn btn-primary btn-touch btn-block" href="Paid.dc.html">${ic("hand-coins")}Take US$25.00${kbdIn("Enter")}</a>` }) })));
board("Paid", "Paid: change due, fiscalised, points, then the next sale", R_CASH, frame(sellScreen({ customer: "Rufaro Chipunza", tray: trayCash({ body:
  `<div class="wait" role="status" aria-live="polite"><span class="status status-success" style="color:var(--color-ink);font-weight:500">Paid in cash, S-005080</span><span class="muted num" style="font-size:var(--text-13)">08:16</span></div><div class="tender" style="box-shadow:var(--shadow-ring)"><span class="l">Give back</span><span class="tender-figure">US$3.32</span></div><dl class="attrs"><dt>Receipt</dt><dd>Fiscalised by ZIMRA, <span class="num" style="text-align:left">00418-3321</span></dd><dt>Rufaro</dt><dd>+21 points, 1,261 now</dd></dl><div class="btn-group" role="group" aria-label="Receipt" style="display:flex">${btn("Print receipt", "printer", "btn-touch grow")}${btn("No receipt", "x", "btn-touch grow")}</div><div class="grow"></div><a class="btn btn-primary btn-touch btn-block" href="SellEmpty.dc.html">${ic("plus")}Next sale${kbdIn("Enter")}</a>` }) })));
board("NoMatch", "When nothing matches: say what was searched, keep the sale", R_CASH, frame(sellScreen({ query: "cooking oyl", mainBody: `<div class="empty">${ic("magnifying-glass", "glyph")}<h2>No product called “cooking oyl”</h2><p>Check the spelling or scan the barcode. Products are added in the back office.</p>${btn("Clear the search", "x")}</div>` })));
const OFF = [["Bread, white loaf", "2", "US$2.00"], ["Eggs", "6", "US$1.20"], ["Coke, 2L", "1", "US$2.00"], ["Matches, box", "4", "US$0.40"]];
board("SavedHere", "No connection at Take: the sale is kept here and says so", R_CASH, frame(sellScreen({ lines: OFF, rows: [["Before discounts", "US$5.60"], ["VAT where it applies, included", "US$0.27"]], total: "US$5.60", count: "4 items", barOpts: { offline: true }, banner: `<div class="banner banner-warning">${ic("wifi-slash")}<span><b style="font-weight:500">No connection since 09:10.</b> Cash sales are saved on this till and sent when it is back. Card and mobile money still need their reference.</span></div>`, tray: trayCash({ total: "US$5.60", body:
  `<div class="wait" role="status" aria-live="polite"><span class="status status-warning" style="color:var(--color-ink);font-weight:500">Saved on this till</span><span class="muted num" style="font-size:var(--text-13)">09:14</span></div><div class="tender" style="box-shadow:var(--shadow-ring)"><span class="l">Give back from US$10.00</span><span class="tender-figure">US$4.40</span></div><p class="muted" style="font-size:var(--text-13);text-wrap:pretty">Its sale number and fiscal receipt come when it is sent. Nothing else to do: it goes up on its own.</p><div class="btn-group" role="group" aria-label="Receipt" style="display:flex">${btn("Print a slip", "printer", "btn-touch grow")}${abtn("Waiting to send", "list", "Waiting", "btn-touch grow")}</div><div class="grow"></div><a class="btn btn-primary btn-touch btn-block" href="SellEmpty.dc.html">${ic("plus")}Next sale</a>` }) })));

// Row 2: hold, recall, mobile money --------------------------------------------------
const R_HOLD = "2  Mai Tino comes back with her phone: hold, recall, mobile money";
const MAI = [["Sugar, 2kg", "1", "US$2.40"], ["Bread, white loaf", "2", "US$2.00"], ["Coke, 2L", "1", "US$2.00"]];
const R_MAI = [["Before discounts", "US$6.40"], ["VAT where it applies, included", "US$0.27"]];
const holdPop = `<div class="float" style="right:150px;top:56px"><div class="pop pop-arrow" role="dialog" aria-label="Hold this sale" style="overflow:visible"><div class="pop-body"><div class="field"><label for="hold-n">Name it <span class="opt">optional</span></label><input class="input input-lg" id="hold-n" value="Mai Tino, fetching cash"><span class="help">It waits under Held until this shift closes.</span></div></div><div class="pop-foot"><span class="kbd" style="margin-right:auto">Esc</span><a class="btn btn-ink" href="Held.dc.html">${ic("pause-circle")}Hold the sale${kbdIn("Enter")}</a></div></div></div>`;
board("Hold", "Hold: a name, so whoever is at the till finds it", R_HOLD, frame(sellScreen({ lines: MAI, rows: R_MAI, total: "US$6.40", count: "3 items" }).replace("</aside></div>", holdPop + "</aside></div>")));
const heldRow = (code, label, when, n, amt, href) => `<div class="row" style="display:grid;grid-template-columns:96px minmax(0,1fr) 120px 96px auto;gap:var(--space-16)"><span class="code num" style="text-align:left">${code}</span><span class="truncate"><span style="color:var(--color-ink)">${label}</span> <span class="muted">${n}</span></span><span class="muted num" style="text-align:left">${when}</span><span class="num" style="color:var(--color-ink)">${amt}</span><span style="display:flex;gap:var(--space-8);justify-content:flex-end"><div class="btn-group" role="group" aria-label="${code}"><a class="btn" href="${href}.dc.html">${ic("play-circle")}Recall</a><a class="btn btn-icon" href="HeldDiscard.dc.html" aria-label="Discard ${code}">${ic("trash")}</a></div></span></div>`;
