// ── Shell B: wrap every in-till board in the rail ──────────────────────────────
const RAILS = [["shopping-cart", "Till", "Sell1", "till"], ["pause-circle", "Held", "Held", "held", 2], ["receipt", "History", "History", "history"], ["cash-register", "Shift", "Shift", "shift"],
  ["users", "Customers", "Customers", "customers"], ["tag", "Price check", "PriceCheck", "price"], ["chart-bar", "Reports", "Reports", "reports"]];
const railNav = (on, who) => `<nav class="rail-b" aria-label="Till"><a class="who" href="Menu.dc.html" aria-label="${who}, open the menu">${avatar(32)}</a>${RAILS.map(([i, l, h, k, n]) => `<a class="nav" href="${h}.dc.html"${k === on ? ' aria-current="page"' : ""}>${n ? `<span class="count">${n}</span>` : ""}${ic(i)}<span>${l}</span></a>`).join("")}<span class="gap"></span><a class="nav" href="Locked.dc.html">${ic("lock")}<span>Lock</span></a></nav>`;
const RAIL_ON = { ShellB: "till", SellEmpty: "till", Customer: "till", Sell1: "till", PayCash: "till", Paid: "till", NoMatch: "till", SavedHere: "till", Hold: "till", Recall: "till", PayRef: "till", PaidRef: "till", Split: "till",
  Line: "till", Disc: "till", Approve: "till", Discount: "till", Held: "held", HeldDiscard: "held", History: "history", Sale: "history", Refund: "history", Refunded: "history", Void: "history",
  Shift: "shift", MoveCash: "shift", Count: "shift", Check: "shift", EndOfDay: "reports", Waiting: "till", Offline: "till", Menu: "till", PriceCheck: "price", Customers: "customers", Reports: "reports",
  Activity: "", Settings: "", Help: "", LqSell: "till", IdCheck: "till", Ceiling: "till", Bottles: "till", Hours: "till", Case: "till", LqPaid: "till" };
const BACK_TILL = '<a class="btn btn-quiet" href="Sell.dc.html">' + ic("caret-left") + "Till</a>";
for (const b of BOARDS) {
  if (!(b.name in RAIL_ON)) continue;
  const who = b.page === "liquor" ? "Kuda Banda" : "Rudo Moyo";
  let body = b.body.split(BACK_TILL).join("");
  if (!body.startsWith('<div class="frame">')) throw new Error("no frame " + b.name);
  body = '<div class="frame"><div class="shell-b">' + railNav(RAIL_ON[b.name], who) + body.slice('<div class="frame">'.length, -"</div>".length) + "</div></div>";
  b.body = body;
}

// ── Start: the navigation map and the workflows ─────────────────────────────────
const node = (label, href, sub) => `<a class="row" href="${href}.dc.html" style="display:flex;gap:var(--space-12);color:inherit;text-decoration:none"><span class="grow">${label}</span>${sub ? `<span class="muted truncate" style="max-width:60%">${sub}</span>` : ""}${ic("caret-right", "faint")}</a>`;
const group = (title, items) => `<section><div class="group-head" style="padding-left:0;padding-right:0"><h2>${title}</h2></div><div class="list">${items.map(([l, h, s]) => node(l, h, s)).join("")}</div></section>`;
board("Main", "Start here: the till’s map, and the workflows that run through it", "Start", `<div class="frame" style="height:1240px"><div class="page" style="max-width:none;padding:var(--space-48) var(--space-48);display:flex;flex-direction:column;gap:var(--space-32);height:100%;overflow:auto">
<p class="lede-figure" style="max-width:920px">The till is one workbench beside a rail: search, the sale, one button that carries the amount. <span class="q">The rail holds seven doors and Lock; what is weekly sits under the person at its top.</span></p>
<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-48)">
<div style="display:flex;flex-direction:column;gap:var(--space-24)">${group("Before anyone sells", [["Pair this device", "Pair", "a manager’s code"], ["Who is selling?", "WhoSells", "name, then PIN"], ["A first PIN", "PinFirst", "password once"], ["Open the shift", "OpenShift", "the float"], ["Locked", "Locked", "PIN to come back"], ["No longer a till", "NoLonger", "replaced"]])}${group("The person at the top of the rail", [["My activity", "Activity", ""], ["Till settings", "Settings", "unpair at the foot"], ["Help", "Help", ""], ["Change my PIN", "PinPick", "password once"], ["Lock the till", "Locked", "also at the rail’s foot"]])}</div>
<div style="display:flex;flex-direction:column;gap:var(--space-24)">${group("The till", [["The sale", "Sell", "lines, customer, how they pay"], ["Add a customer", "Customer", "popover"], ["A line", "Line", "price, discount, remove"], ["Discount, promotion, points", "Discount", "popover"], ["Hold", "Hold", "popover, with a name"], ["Take cash", "PayCash", "tray: handed over, change"], ["Take mobile money", "PayRef", "tray: the reference"], ["Split between two ways", "Split", "tray"], ["Paid", "Paid", "change due, receipt, next sale"]])}</div>
<div style="display:flex;flex-direction:column;gap:var(--space-24)">${group("The rail", [["Held", "Held", "recall, discard"], ["History", "History", "my sales this shift"], ["A sale", "Sale", "print, refund lines, void"], ["Shift", "Shift", "move cash, cash up"], ["Customers", "Customers", "points, start a sale"], ["Price check", "PriceCheck", ""], ["Reports", "Reports", "my sales today, end of day"], ["Waiting to send", "Waiting", "when the line drops"]])}${group("A manager at the till", [["Approve a discount", "Approve", "password and reason"], ["Approve a refund", "Refund", "in the same window"], ["Void a sale", "Void", "irreversible, asks"], ["End of day", "EndOfDay", "frozen when taken"]])}</div></div>
<section><div class="group-head" style="padding-left:0;padding-right:0"><h2>Workflows, one row each on the General shop page</h2><span class="sum">8 rows, then the liquor store</span></div><div class="list">${[["1  Rudo sells to Rufaro and takes cash", "SellEmpty", "most frequent"], ["2  Mai Tino comes back with her phone", "Hold", "hold, recall, mobile money"], ["3  A dented bottle", "Line", "a discount a manager approves"], ["4  Tapiwa brings back damaged rice", "History", "most at stake"], ["5  A new device and a new cashier", "Pair", "crosses roles"], ["6  Rudo cashes up short; Farai takes the report", "Shift", "the end of the day"], ["7  The line drops, and the rest of the till", "Offline", ""], ["8  The same till on a Kora", "PhoneSell", "390 wide"], ["The liquor store", "LqSell", "deposits, ID, ceilings, hours, cases"]].map(([l, h, s]) => node(l, h, s)).join("")}</div></section></div></div>`, { w: 1440, h: 1240, page: "start" });

// ── Write ─────────────────────────────────────────────────────────────────────
const FONTS = `<link href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible+Next:wght@400;500;600&amp;family=IBM+Plex+Mono:wght@400;500;600&amp;display=swap" rel="stylesheet">`;
fs.copyFileSync(path.join(here, "gen/tokens.css"), path.join(OUT, "tokens.css"));
fs.copyFileSync(KIT, path.join(OUT, "kit.css"));
fs.copyFileSync(path.join(here, "till.css"), path.join(OUT, "till.css"));
for (const f of ["tokens.css", "kit.css", "till.css"]) fs.copyFileSync(path.join(OUT, f), path.join(CANVAS, f));
for (const b of BOARDS) b.body = b.body.replace(/href="Sell\.dc\.html"/g, 'href="Sell1.dc.html"');
for (const b of BOARDS) {
  const html = `<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${b.name}</title>${FONTS}<link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="kit.css"><link rel="stylesheet" href="till.css"></head><body style="background:var(--color-surface)">${b.body}</body></html>`;
  fs.writeFileSync(path.join(OUT, b.name + ".html"), html.replace(/href="([A-Za-z0-9]+)\.dc\.html"/g, 'href="$1.html"').split("__ECOCASH__").join("ecocash.png"));
  const props = JSON.stringify({ $preview: { width: b.w, height: b.h } });
  const dc = `<!doctype html>\n<html lang="en-GB">\n<head>\n<meta charset="utf-8">\n<title>${b.title.replace(/<[^>]+>/g, "").split("  ").pop()}</title>\n<script src="./support.js"></script>\n<link rel="stylesheet" href="tokens.css">\n<link rel="stylesheet" href="kit.css">\n<link rel="stylesheet" href="till.css">\n</head>\n<body>\n<x-dc>\n<helmet>\n${FONTS}\n<style>body{margin:0;background:#ffffff}</style>\n</helmet>\n${b.body}\n</x-dc>\n<script type="text/x-dc" data-dc-script data-props='${props}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n</script>\n</body>\n</html>\n`;
  fs.writeFileSync(path.join(CANVAS, b.name + ".dc.html"), dc.split("__ECOCASH__").join("/_blob/940835b0c1c82a1f85cc076f5b69302f"));
}
fs.writeFileSync(path.join(here, "boards.json"), JSON.stringify(BOARDS.map(({ name, title, row, w, h, page }) => ({ name, title, row, w, h, page })), null, 1));
